\label{lemma: iterate}
Let $\Phi$ be a first-order sentence on words over $\Sigma$. There
are a complete finite deterministic automaton $\mathcal B$
recognizing $\{w:w\models\Phi\}$ and an integer $N\geq1$ such that
\begin{equation}\label{eq: iterate}
 \delta_{\mathcal B}(r,v^N)=\delta_{\mathcal B}(r,v^{N+1})
 \qquad(r\in Q_{\mathcal B},\ v\in\Sigma^*).
\end{equation}

We say that an $\ell\times m$ gridded figure $\left(F,G_{\ell\times m}\right)$ is \textit{compatible} with a matrix $M$ if $M$ is an $\ell \times m$ matrix with entries in $\{-1,0,1\}$ such that for each $\left(i,j\right)\in\left[\ell \right]\times\left[m\right]$ we have 
    \begin{align*}
    F\cap C_{i,j} \textrm{ is }\left\{\begin{array}{ll}
	   \text{empty } & \text{if }M_{i,j}=0,\\
      \text{a (possibly empty) increasing segment} & \text{if }M_{i,j}=1,\\
	   \text{a (possibly empty) decreasing segment} & \text{if }M_{i,j}=-1.
    \end{array}\right.
    \end{align*}
    Here we say that a set of points $\{(x_i, y_i): i \in [t]\}$ in $\mathbb{R}^2$ with $x_1<x_2<\ldots <x_t$ forms an \emph{increasing segment} if $y_1<y_2<\ldots <y_t$, and a \emph{decreasing segment} if $y_1>y_2>\ldots > y_t$.

\label{def: left greedy}
    Given a permutation $\sigma$ and a gridding $G$, we define the \emph{left-greedy order} $<_{LG}$ on equivalence classes of gridded figures with gridding $G$ that induce $\sigma$ by letting $(F, G)<_{LG}(F', G')$ if one of the following occurs:
    \begin{enumerate}
	   \item there exists an index $i_0$ such that for all $i<i_0$ and for all $j$, the number of points of $F$ and $F'$ in the $(i,j)$-th cells of their respective griddings are equal, but there are strictly more points of $F$ than of $F'$ in the cells located in the $i_0$-th column;
	   \item there exist indices $i_0$ and $j_0$ so that for every $(i,j)$ with either $i < i_0$, or $i = i_0$ and $j < j_0$,  the number of points of $F$ and $F'$ in the $(i,j)^{th}$ cell of their respective griddings are equal, the number of points of $F$ and $F'$ in the cells located in the $i_0$-th column are equal,     
       but there are strictly more points of $F$ than of $F'$ in the $(i_0,j_0)$-th cell.
    \end{enumerate}

\label{def: LG order}
    Let $\mathcal{P}$ and $\mathcal{Q}$ be two permutation classes. Let $\tau\left[\sigma_{1},\dots,\sigma_{k}\right]$ and $\tau'\left[\sigma'_{1},\dots,\sigma'_{k'}\right]$ be two $\mathcal{Q}$-decompositions of the same permutation in $\mathcal{P}[\mathcal{Q}]$, we say that $\tau\left[\sigma_{1},\dots,\sigma_{k}\right]<_L\tau'\left[\sigma'_{1},\dots,\sigma'_{k'}\right]$ if one of the following holds:
    \begin{enumerate}
        \item $\vert \tau \vert =k <k' =\vert \tau'\vert$; or
        \item $k=k'$ and there exists $i_0\in [k]$ such that for all $i\in [i_0-1]$ we have $\vert \sigma_{i}\vert =\vert \sigma'_{i} \vert$ but $\vert \sigma_{i_0}\vert >\vert \sigma'_{i_0}\vert$.
    \end{enumerate}

Given a  $\ell\times m$ $\star$-isolated forest matrix $M$, the standard $\ell \times m$ gridding $G$ and integers $d,k\in \mathbb{Z}_{+}$, we define $\mathrm{Geom}^{\#}(M)_{d,k}$ to be the collection of all equivalence classes which contain a gridded figure $(F,G)$ satisfying the following:
    \begin{enumerate}
        \item if $M_{i,j}=0$ then $F\cap C_{i,j}=\emptyset$;
        \item if $M_{i,j}=+1$, we have $F\cap C_{i,j} \subseteq \left\{(i-1, j-1)+(t,t): \ t\in (0,1)\right\}$, while if $M_{i,j}=-1$ we have $F\cap C_{i,j} \subseteq \left\{(i-1, j-1)+(t,1-t): \ t\in (0,1)\right\}$;
       \item if $M_{i,j}=\star$, then $F\cap C_{i,j}$ induces a permutation from ${\widetilde{\mathcal{O}}_{k}}^{[d]}$.
    \end{enumerate}
    Finally we let $\mathrm{Geom}(M)_{d,k}$ denote the collection of all permutations induced by an equivalence class in $\mathrm{Geom}^{\#}(M)_{d,k}$.

\label{thm:Main O_K}
    Let $d$ and $k$ be positive integers. There exists a regular language $L_{d,k}$ and a bijection $f_{d,k}:L_{d,k} \rightarrow \tilde{\mathcal{O}}_{\textit{k}}^{\left[\textit{d}\right]}$ so that for every first-order or monadic second-order sentence $\Psi$ on $\tilde{\mathcal{O}}_{\textit{k}}^{\left[\textit{d}\right]}$ there exists a first-order or a monadic second-order sentence $\Phi$  on $L_{d,k}$ for which 
    \[\{w \in L_{d,k}: w \models \Phi\} = \{w \in L_{d,k}: f_{d,k}(w) \models \Psi\}.\]

Let $k$ be a fixed positive integer. As the base case $d = 1$, consider the first-order sentence $\Gamma_{1}$ given by 
\begin{align*}
&\ \bigl( (\exists x:w_x=a_{\mathrm{inc}})\land (\forall x\colon w_x=a_{\mathrm{inc}})\bigr)\\
&\lor\bigl( (\exists x \exists y: (x < y) \land (w_x=a_{\mathrm{dec}})\land w_y = a_{\mathrm{dec}}) \land (\forall x\colon w_x=a_{\mathrm{dec}})\bigr)\\
&\lor\bigvee_{\tau\in\mathcal Q_k}\bigl(\Gamma_\tau\land\forall x\colon\rho_2(w_x)=\tau\bigr),
\end{align*}
where $\Gamma_{\tau}$ is the first-order sentence given by
\begin{align*}
& \bigwedge_{i=1}^{|\tau|} \left(\exists j_1 \forall j_2: w_{j_1} = a_{\tau,i} \land (w_{j_2} = a_{\tau,i} \implies j_1 = j_2)\right)
\\& \land \left(\forall j_1 \forall j_2: (j_1 < j_2 \implies \rho_3(w_{j_1}) < \rho_3(w_{j_2}))\right).
\end{align*}
In order to check that $\Gamma_{1}$ satisfies the required properties. we start by observing that when $w_1 = a_{\mathrm{inc}}$ the first line of $\Gamma_1$ ensures that we have $w \models \Gamma_1$ if and only if $w = a_{\mathrm{inc}}^n$ for any $n \in \mathbb{Z}_+$. Similarly, whenever $w_1 = a_{\mathrm{dec}}$, the second line ensures that we have $w \models \Gamma_1$ if and only if $w = a_{\mathrm{dec}}^n$ for any $n \in \mathbb{Z}_{\geq 2}$. In both instances, these two conditions are equivalent to the condition $g_{1}(w) \neq \star$. 

Finally, consider the case when $\rho_2(w_1) = \tau$ for some $\tau \in \mathcal{Q}_k$. In this case, we have $g_1(w) \neq \star$ if and only if $w = w^{(\tau)}$, where $w^{(\tau)} := a_{\tau,1} \dots a_{\tau,|\tau|}$. Now suppose that $w \models \Gamma_{1}$ and $\rho_2(w_1) = \tau$. Then, (i) the first part of the top line of $\Gamma_\tau$ ensures that each $a_{\tau,i}$ for $i \in [|\tau|]$ occurs at least once in $w$, (ii) the second part of the top line of $\Gamma_\tau$ ensures that each letter $a_{\tau,i}$ occurs exactly once in $w$, and (iii) the second line ensures that the letter $a_{\tau,i}$ occurs before $a_{\tau,j}$ in $w$ whenever $i < j$. It is evident that the only word satisfying all three of these conditions is $ w^{(\tau)}$, which completes the proof of the base case. 

Suppose that $d \geq 2$ and that $\Gamma_{d-1}$ satisfies the required conditions for $d-1$. Define auxiliary first order formulae $\psi_{\neq}(i,j,t)$ and $\psi_{=}(i,j)$ as 
\begin{align*}
    (i\neq j) \implies \left(\rho_{4}\left(w_{i}\right)=\left\{ L\right\} \land\rho_{4}\left(w_{j}\right)=\{R\}\land\left(i<t<j\implies\rho_{4}\left(w_{t}\right)=\emptyset\right) \land (\Gamma_{d-1})_{i,j}\right)
\end{align*}
and 
\begin{align*}
    (i=j) \implies \left(\rho_{4}\left(w_{i}\right)=\left\{ L,R\right\} \land(\Gamma_{d-1})_{i,j}\right)
\end{align*}
respectively. Note that both of them are first-order formulae by Lemma~\ref{lemma: restriction to sub-words preserves FOS}. Define $\Gamma_{d}$ to be the first-order sentence  
    \begin{align*}
& \forall i: (\rho_2(w_i) = \rho_2(w_1))
\\& \land \bigwedge_{\tau \in \mathcal{Q}_k} \left((\rho_2(w_1) = \tau  )\implies (\forall i \forall j:i < j \implies \rho_3(w_i) \leq \rho_3(w_j))\right)
\\& \land \bigwedge_{\tau\in\mathcal{Q}_{k}}\left(\left(\rho_{2}\left(w_{1}\right)=\tau\right)\implies\left(\bigwedge_{j=1}^{\left|\tau\right|}\left(\exists i: \rho_3(w_i) = j \land (\Gamma_{d-1})_{j}\right)\right)\right)
\\& \land  \left(\rho_2(w_1) \in \{\mathrm{inc},\mathrm{dec}\} \implies \left(\forall s \exists i \exists j\forall t: \left(i\leq s\leq j\right)\land \psi_{\neq}(i,j,t) \land \psi_{=}(i,j)\right)\right)
\\& \land \left(\rho_2(w_1) = \mathrm{dec} \implies \exists a\exists b:\left(a<b\land L\in\rho_4(w_a)\land L\in\rho_4(w_b)\right)\right).
\end{align*}
We start by checking that for every $w$ with $w \models \Gamma_d$ we have $g_d(w) \neq \star$. The first line of $\Gamma_d$ ensures that $w$ is consistent. Let $\tau \in \mathcal{Q}_k\cup\{\mathrm{inc},\mathrm{dec}\}$ be the profile $\tau$ of $w$, and first consider the case when $\tau \in \mathcal{Q}_k$. Thus, only the second and third line of $\Gamma_d$ are relevant in this case. 

Let $u_j$ denote the sub-word of $w$ consisting of those $w_i$ with $\rho_3(w_i) = j$. The condition $\exists i: \rho_3(w_i) = j$ ensures that $u_j$ is non-empty for every $ 1\leq j \leq |\tau|$, and the second line ensures that $w$ coincides with the concatenation $u_1\dots u_{|\tau|}$. Finally, the condition $w \models (\Gamma_{d-1})_j$ is equivalent to having $\rho_1(u_j) \models \Gamma_{d-1}$ for every $1 \leq j \leq |\tau|$, which by induction implies that $g_{d-1}(\rho_1(u_i)) \neq \star$ for every $1 \leq i\leq |\tau|$. In particular, we must have  $g_d(w) \neq \star$, as required. 

Now suppose that $\tau \in \{\mathrm{inc},\mathrm{dec}\}$. For each $s$, let $i(s)$ and $j(s)$ denote the indices chosen so that the fourth line is satisfied for this particular value of $s$, and write $u^{(s)}$ for the sub-word $w_{i(s)}\dots w_{j(s)}$. 

\begin{claim}\label{claim: I,D decomposes properly}
    For each $s$, the sub-word $u^{(s)}$ satisfies the conditions~\eqref{eq: consistent conditions for I,D - 1} and~\eqref{eq: consistent conditions for I,D - 2}. In particular, the word $w$ can be expressed as a concatenation $w = u_1\dots u_\ell$ for some $u_1,\dots,u_\ell$ chosen so that for every $j$ we have $u_j = u^{(s_j)}$ for some $s_j$. 
\end{claim}
\begin{proof}
    Given an index $s$, we start with the case when $i(s) = j(s) = s$. In this case, we must have $w \models \psi_{=}(i(s),j(s))$, which in turn implies that $\rho_4(w_{i(s)}) = \{L,R\}$. Thus, the word $u^{(s)}$ that  consists of a single letter $w_{i(s)}$ trivially satisfies both of the conditions~\eqref{eq: consistent conditions for I,D - 1} and~\eqref{eq: consistent conditions for I,D - 2}. 

    Now suppose that $i(s) \neq j(s)$, and thus we must have $i(s) < j(s)$.  Thus the fourth line ensures that $w \models \forall t: \psi_{\neq}(i(s),j(s),t)$, which by construction of $\psi_{\neq}$ implies
    \begin{enumerate}
        \item[(i)] $\rho_4(w_{i(s)}) = \{L\}$,
        \item[(ii)] $\rho_4(w_{j(s)}) = \{R\}$, and 
        \item[(iii)] $\rho_4(w_t) = \emptyset$ for every $i(s) < t < j(s)$. 
    \end{enumerate}
    These conditions together are clearly equivalent to the fact that $u^{(s)}$ satisfies both of the conditions~\eqref{eq: consistent conditions for I,D - 1} and~\eqref{eq: consistent conditions for I,D - 2}, which proves the first part of the claim. 

    To prove the second part, observe that the sub-words $u^{(s)}$ cover $w$ as each $w_s$ is trivially contained in $u^{(s)}$. In addition, recall that each $u^{(s)}$ consists of a set of contiguous letters. Hence, it suffices to prove that for each $s \neq s'$, the sub-words $u^{(s)}$ and $u^{(s')}$ are either identical or disjoint. 

    Suppose that $s \neq s'$ are chosen so that $u^{(s)}$ and $u^{(s')}$ are neither identical nor disjoint. Since both of them consists of a contiguous set of letters, we must have $i(s) \in [i(s'),j(s')]$ or $i(s')\in [i(s),j(s)]$. By symmetry, we may assume that the first case occurs. 

    Since $u^{(s')}$ satisfies property~\eqref{eq: consistent conditions for I,D - 1} and $L \in \rho_4(w_{i(s)})$, we must have $i(s) = i(s')$. As $u^{(s)}$ and $u^{(s')}$ are not identical, we must have $j(s) \neq j(s')$, and by symmetry, we may assume that $j(s) < j(s')$. Since $R \in \rho_4(w_{j(s)})$ and $j(s) \in [i(s),j(s')]$ this contradicts the fact that $u^{(s')}$ satisfies property~\eqref{eq: consistent conditions for I,D - 2}. This completes the proof of Claim~\ref{claim: I,D decomposes properly}. 
\end{proof}
    \noindent Claim~\ref{claim: I,D decomposes properly} implies that any $w$ with $w \models \Gamma_d$ and whose profile is in $\{\mathrm{inc},\mathrm{dec}\}$ decomposes as a concatenation $w = u_1\dots u_\ell$, where the sub-words $u_i$ satisfy properties~\eqref{eq: consistent conditions for I,D - 1} and~\eqref{eq: consistent conditions for I,D - 2}. In addition, the last part of both $\psi_{\neq}$ and $\psi_{=}$ implies that we must also have $\rho_1(u_i) \models \Gamma_{d-1}$ for each $i$, whence the inductive assumption implies that $g_{d-1}(\rho_1(u_i)) \neq \star$ for each $i$. When $\tau = \mathrm{dec}$, the last line of $\Gamma_d$ ensures that $\ell\geq 2$: as the letters marked with $L$ coincide with the first letters in the sub-words $u_i$ and there must be at least two such letters $L$, we indeed have $\ell \geq 2$. Thus we conclude that $g_d(w) \neq \star$. The proof of the converse direction follows similarly, we omit the details.

\label{thm: FO correspondence}
    Let $v^{(f)}_1,\dots,v^{(f)}_{c_1},v^{(b)}_1,\dots,v^{(b)}_{c_2}$ denote variables (either first- or second-order variables), with $v^{(f)}_i$'s corresponding to free and $v^{(b)}_i$'s corresponding to bound variables. Let $\psi(v^{(f)}_1,\dots,v^{(f)}_{c_1})$ denote a monadic second-order formula in $\mathrm{TOTO}$ given in disjunctive normal form, i.e.\
    \begin{align*} 
        \psi(v^{(f)}_1,\dots,v^{(f)}_{c_1}) = Q_1 v^{(b)}_1\dots Q_{c_2} v^{(b)}_{c_2}: \left[\left(p_{1,1} \land \dots \land p_{1,a_1}\right) \lor \dots \lor \left(p_{b,1} \land \dots  \land p_{b,a_b}\right)\right],
    \end{align*}
    where each $p_{i,j}$ is an atomic formula or its negation involving variables in $v^{(f)}_1,\dots,v^{(f)}_{c_1}$,\\$v^{(b)}_1,\dots,v^{(b)}_{c_2}$. There exists a monadic second-order formula $\phi$ of the form 
    \begin{align}  \label{eq: phi formula}
        \phi(\nu^{(f)}_1,\dots,\nu^{(f)}_{c_1}) = Q_1 \nu^{(b)}_1 \dots Q_{c_2} \nu^{(b)}_{c_2}: \left[\left(q_{1,1} \land \dots \land q_{1,a_1}\right) \lor \dots \lor \left(q_{b,1} \land \dots \land q_{b,a_b}\right)\right]
    \end{align}
    satisfying the following properties:
    \begin{enumerate}
        \item[(i)] each variable $\nu^{(f)}_i$ or $\nu^{(b)}_j$ has the same order as the respective variable $v^{(f)}_i$ or $v^{(b)}_j$;
        \item[(ii)] each formula $q_{i,j}$ depends only on the formula $p_{i,j}$; and
        \item[(iii)] for each $a_1,\dots,a_{c_1}$ and $w \in \Sigma_d^*$ satisfying $w \models \Gamma_d$, we have $w \models \phi(a_1,\dots,a_{c_1})$ if and only if $f_d(w) \models \psi(\alpha_w(a_1),\dots,\alpha_w(a_{c_1}))$.
    \end{enumerate}

    In addition, if $\psi$ is a first-order formula, then so is $\phi$.

\label{lemma: easy cases = and in}
    Let $w \in \Sigma_d^*$ be chosen so that $w \models \Gamma_d$. 
    \begin{enumerate}
        \item Let $\psi(x,y)$ denote the $\mathrm{TOTO}$-formula given by $x = y$, and $\phi(x',y') \in \mathrm{FO}(\Sigma_{d}^*)$ given by $x' = y'$. We have $w \models \phi(a,b)$ if and only if $f_d(w) \models \psi(\alpha_w(a), \alpha_w(b))$. 
        \item Let $\psi(x,z)$ denote the $\mathrm{MSO}$-$\mathrm{TOTO}$ formula given by $x \in z$, and $\phi(x',z')$ be the monadic second-order formula given by $x' \in z'$. We have $w \models \phi(a,b)$ if and only if $f_d(w) \models \psi(\alpha_w(a), \alpha_w(b))$. Here, we write $\alpha_w(b) = \{\alpha_w(c): c \in b\}$. 
    \end{enumerate}

The proof is by induction on $d$, with the base case $d = 1$ covered by Lemma~\ref{lemma: base case of leq_1 correspondence}. Suppose that the statement holds for $d -1$, and let $w\in \Sigma_d^*$ be chosen so that $w \models \Gamma_d$. Thus $w$ is consistent and decomposes properly. Let $u_1,\dots,u_m$ be chosen so that $w$ decomposes as $w = u_1\dots u_m$. For each $i \in \{1,\dots,m\}$ write $\sigma_i = f_{d-1}(\rho_1(u_i))$, and let $\tau'$ be chosen so that $f_d(w) = \tau'[\sigma_1,\dots,\sigma_m]$, and write $\tau$ for the profile of $w$. We split the proof into three cases based on whether we have $\tau \in \mathcal{Q}_k$, $\tau = \mathrm{dec}$ or $\tau = \mathrm{inc}$. 

    \textbf{Case 1, $\tau \in \mathcal{Q}_k$:} Since $\tau \in \mathcal{Q}_k$, we have $\tau' = \tau$. From the expression of $\xi_{s,d}$ it immediately follows that the condition $w \models \xi_{s,d}(a,b)$ is equivalent to $w \models P_{s,\tau}(a,b)$. For convenience, write $p = \alpha_w(a)$, $q = \alpha_w(b)$, $i_p = \rho_3(w_a)$ and $i_q = \rho_3(w_b)$. Thus $p$ belongs to the interval $\sigma_{i_p}$ and $q$ belongs to the interval $\sigma_{i_q}$ in the inflation 
    \begin{align}\label{eq: important inflation}
        f_d(w) = \tau'[\sigma_1,\dots,\sigma_m]. 
    \end{align}
    First suppose that $i_p \neq i_q$. As $p$ and $q$ belong to different intervals in inflation~\eqref{eq: important inflation}, the relative order of $p$ and $q$ can be determined using the indices $i_p$ and $i_q$. Indeed, the condition $p \leq_1 q$ is equivalent to $i_p < i_q$, and the condition $p \leq_2 q$ is equivalent to $\tau(i_p) < \tau(i_q)$. These conditions are clearly equivalent to the condition on the  top line of $P_{s,\tau}$. 

    Now suppose that $i_p = i_q = i$. In this case, both $p$ and $q$ belong to the same interval $\sigma_{i}$, and the indices $a$ and $b$ belong to the same sub-word $u_i$, for which we have $f_{d-1}(\rho_1(u_i)) = \sigma_i$ and $\sigma_i \in \widetilde{\mathcal{O}}_k^{[d-1]}$. Thus the inductive assumption implies that $\xi_{s,d}$ satisfies the required properties. 

    \textbf{Case 2, $\tau =\mathrm{dec} $:} Note that the equation~\eqref{eq: important inflation} remains valid, but the permutation $\tau'$ is a monotone decreasing permutation, whose (unknown) length we denote by $\ell$. As before, we write $p = \alpha_w(a)$ and $q = \alpha_w(b)$, and choose $i_p$ and $i_q$ to be the indices in $\{1,\dots,\ell\}$ so that $w_a$ and $w_b$ are contained in $u_{i_p}$ and $u_{i_q}$ respectively. In particular, $i_p$ and $i_q$ play the same role as the corresponding indices in the previous case (however, in this case we cannot define them using the function $\rho_3$ as it does not apply to words whose type is $\mathrm{inc}$ or $\mathrm{dec}$). 
    \begin{claim}\label{claim: simple P2 and P3}
        We have $w \models P_{2}(a,b)$ if and only if $i_p < i_q$, and we have $w \models P_{3}(a,b)$ if and only if $i_q < i_p$
    \end{claim}
    \begin{proof}
        First suppose that $w \models P_2(a,b)$, and let $i = i_*$ be chosen so that $a \leq i_*$, $i_* < b$ and $R \in \rho_4(w_{i_*})$. Let $s$ be chosen so that $w_{i_*}$ is contained in $u_s$. Hence, the condition $a \leq i_*$ implies that $i_p \leq s$, and the conditions $i_* < b$ and $R \in \rho_4(w_{i_*})$ imply that $s < i_q$. Note that in the second conclusion, the fact $R \in \rho_4(w_{i_*})$ ensures that $w_{i_*}$ is the last letter in the sub-word $u_s$, which in turn ensures that $w_b$ cannot be contained in $u_s$ as $b > i_*$. Hence, it follows that $i_p \leq s <  i_q$, as required.

        If $i_p < i_q$, we may simply choose the value of $i$ in $P_2$ to be the index of the last letter in $u_{i_p}$, which proves the converse. The second assertion follows analogously. 
    \end{proof}
    \begin{claim} \label{claim: P4}
        We have $w \models P_{4,s}(a,b)$ if and only if $i_p = i_q$, and the sub-word $u_{i_p}$ satisfies $\rho_1(u_{i_p}) \models \xi_{s,d-1}(a,b)$.
    \end{claim}
    \begin{proof}
        First suppose that $w \models P_{4,s}(a,b)$, and let $i = i_*$ and $j = j_*$ be chosen so that the remaining formula is satisfied for all values of  $\ell$. The third and fourth lines of $P_{4,s}$ imply that $i_*$ and $j_*$ are the first and last index of some $u_t$, and the first line implies that $w_a$ and $w_b$ must both belong to $u_t$. In particular, we must have $t = i_p = i_q$. Finally, the last line implies that $\rho_1(u_t) \models \xi_{s,d-1}(a,b)$, as required. In order to prove the converse direction,  choose the values of $i$ and $j$ to be the indices of the left and right endpoints of the sub-word $u_{i_p}$. 
    \end{proof}

    Suppose that $a$ and $b$ are chosen so that $p \leq_s q$. Our aim is to show that we have $w \models \xi_{s,d}(a,b)$. First consider the case when $s = 1$ and $i_p \neq i_q$. In this case, $p \leq_s q$ is equivalent to $i_p < i_q$, as $p$ belongs to the interval corresponding to $\sigma_{i_p}$ and $q$ belongs to the interval  corresponding to $\sigma_{i_q}$. By Claim~\ref{claim: simple P2 and P3}, this is equivalent to having $w\models P_2(a,b)$, which in turn implies that $w \models \xi_{1,d}(a,b)$ by considering the third line of $\xi_{1,d}$. 

    Now suppose that $s = 2$ and $i_p \neq i_q$.  In this case, $p \leq_s q$ is equivalent to $i_q < i_p$, as $\tau'$ is a monotone decreasing permutation. By Claim~\ref{claim: simple P2 and P3}, this is equivalent to having $w \models P_3(a,b)$, which due to the last line of $\xi_{s,d}$ implies that $w \models \xi_{2,d}(a,b)$. 

    Finally, suppose that $i_p = i_q = t$. In this case, both $p$ and $q$ belong to the same inflated block $\sigma_{t}$, and both letters $w_a$ and $w_b$ belong to the same sub-word $u_t$. Since $p \leq_s q$, the inductive hypothesis implies that  $\rho_1(u_t) \models \xi_{s,d-1}(a,b)$. In particular, Claim~\ref{claim: P4} implies that $w \models P_{4,s}(a,b)$. Thus, by considering the appropriate line in the construction of $\xi_{s,d}$ it is easy to verify that we have $w \models \xi_{s,d}(a,b)$, as required. 

    Proving that $w \models \xi_{s,d}(a,b)$ implies that $p \leq_s q$ follows by using a similar argument, we omit the details. 

    \textbf{Case 3, $\tau = \mathrm{inc}$:} The analysis is similar to the one presented in Case 2. We omit the details.

For each variable $v_i^{(\beta)}$ with $\beta \in \{f,b\}$ occurring in $\psi$ either as a bound or free variable, we define $\nu_i^{(\beta)}$ to be a variable of the same order, and we say that $\nu_i^{(\beta)}$ is the corresponding variable in $\phi$.  Given a variable $x_{\psi}$ occurring in $\psi$, we write $x_{\phi}$ for the corresponding variable in $\phi$. Define the formulae $q_{i,j}$ as follows:
    \begin{enumerate}
        \item[(i)] if $p_{i,j} := (x_\psi = y_\psi)$, we set $q_{i,j} := (x_{\phi} = y_\phi)$;
        \item[(ii)] if $p_{i,j} := (x_\psi \in  y_\psi)$, we set $q_{i,j} := (x_\phi \in  y_\phi)$;
        \item[(iii)] if $p_{i,j} := (x_\psi \leq_s  y_\psi)$ for $s \in \{1,2\}$, we set $q_{i,j} := \xi_{s,d}(x_\phi, y_\phi)$; and
        \item[(iv)] if $p_{i,j}$ is a negation of an atomic formula, we define $q_{i,j}$ to be the negation of the appropriate formula constructed as above. 
    \end{enumerate}
    Having defined the formulae $q_{i,j}$, define $\phi(\nu_{1}^{(f)},\dots,\nu_{c_1}^{(f)})$ to be the formula given by equation~\eqref{eq: phi formula}. For convenience, write $\psi'(v^{(f)}_1,\dots,v^{(f)}_{c_1},v^{(b)}_1,\dots,v_{c_2}^{(b)})$ for the quantifier-free part of $\psi$, i.e.\  
    \[\psi'(v^{(f)}_1,\dots,v^{(f)}_{c_1},v^{(b)}_1,\dots,v_{c_2}^{(b)}) := (p_{1,1} \land \dots \land p_{1,a_1}) \lor \dots \lor (p_{b,1} \land \dots \land p_{b,a_b}),\]
    and similarly write $\phi'(\nu ^{(f)}_1,\dots,\nu ^{(f)}_{c_1},\nu ^{(b)}_1,\dots,\nu_{c_2}^{(b)})$  for the quantifier-free part of $\phi$. 
    Given an integer $t \in \{0,\dots,c_2\}$ and constants $a_1,\dots,a_{c_1}$ and $b_{1},\dots,b_{t}$, define 
    \begin{align}\label{eq: restricted psi}
        \psi_t(a_1,\dots,a_{c_1},b_1,\dots,b_t) := Q_{t+1} v_{t+1}^{(b)} \dots Q_{c_2} v^{(b)}_{c_2}: \psi'(a_1,\dots,a_{c_1},b_1,\dots,b_t,v_{t+1},\dots,v_{c_2}),
    \end{align}
    and similarly define
    \begin{align}\label{eq: restricted phi}
        \phi_t(a_1,\dots,a_{c_1},b_1,\dots,b_t) := Q_{t+1} \nu_{t+1}^{(b)} \dots Q_{c_2} \nu^{(b)}_{c_2}: \phi'(a_1,\dots,a_{c_1},b_1,\dots,b_t,\nu_{t+1},\dots,\nu_{c_2}). 
    \end{align} 
    Write $X \subseteq \{1,\dots,c_2\}$ for the set of indices $t$ for which we have $Q_t = \forall$. Finally, we say that a constant $c_i$ chosen as the value of the variable $x_i$ has \emph{correct order} if $c_i$ and $x_i$ are first-order constant and variable respectively, or they are second-order constant and variable respectively. 

    Having defined the necessary notation, we move on to the main part of the proof. We only prove the reverse direction of the statement as the proof of the other direction follows analogously. That is, we prove that whenever $f_d(w) \models \psi(b_1,\dots,b_{c_1})$ for some constants $b_1,\dots,b_{c_1}$, then $w \models \phi(\alpha_w^{-1}(b_1),\dots,\alpha_w^{-1}(b_{c_1}))$. 

    \begin{claim} \label{claim: extending sequences}
        Let $\underline{s}$ be a $[c_1]$-tuple of constants in $f_d(w)$ with correct orders with respect to the variables $v^{(f)}_i$ chosen so that $f_d(w) \models \psi(s_1,\dots,s_{c_1})$. Let $\underline{t}$ denote the $[c_1]$-tuple of constants in $w$ chosen so that $t_i = \alpha_w^{-1}(s_i)$ for each $i \in [c_1]$, and let $\hat{\underline{u}} = (\hat{u}_i: i \in X)$ denote an arbitrary $X$-tuple of constants in $w$ of the correct orders. There exists a $[c_2]$-tuple of constants $\underline{u}$ for which the following properties hold for every $j \in \{0,1,\dots,c_2\}$:
        \begin{enumerate}
            \item[(i)] if $j \in X$, we have $u_j = \hat{u}_j$;
            \item[(ii)] if $j \not \in X$ and $j > 0$, the choice of $u_j$ only depends on the tuple $\underline{t}$, and on the values of the constants in the tuple $(\hat{u}_i: i \in X, i < j)$; and 
            \item[(iii)] we have $f_d(w) \models \psi_j(s_1,\dots,s_{c_1},\alpha_w(u_1),\dots,\alpha_w(u_j))$. 
        \end{enumerate}
    \end{claim}

    \noindent Before proving the claim, we note that the choice of $t_i = \alpha_w^{-1}(s_i)$ in the statement exists and is unique as $\alpha_w$ is a bijection. 

    \begin{proof}
        We construct the sequence $\underline{u}$ by induction on $j$. The  base case $j = 0$ follows immediately from the assumption that $f_d(w) \models \psi(s_1,\dots,s_{c_1})$ as $\psi_0 = \psi$, and since only the third condition is applicable in this case. Suppose that the statement holds for some $j = i$ with $i \in \{0,\dots,c_2-1\}$. We split the proof into cases based on whether we have $i + 1 \in X$ or $i + 1\not \in X$. 

        \textbf{Case 1, $i + 1 \in X$:} In this case, we set $u_{i+1} = \hat{u}_{i+1}$, and thus the first condition is automatically satisfied. Applying the inductive assumption with the third condition we conclude that 
        \begin{align*}
            f_d(w) \models \forall v_{i+1} Q_{i+2} v_{i+2} \dots Q_{c_2} v_{c_2}: \psi'(s_1,\dots,s_{c_1},\alpha_w(u_1),\dots,\alpha_w(u_i),v_{i+1},\dots,v_{c_2}). 
        \end{align*}
        Here, we are using the fact that $Q_{i+1} = \forall$, which follows from $i+1 \in X$. By choosing $v_{i+1} := \alpha_w(u_{i+1})$, we conclude that
        \begin{align*}
            f_d(w) \models Q_{i+2} v_{i+2} \dots Q_{c_2} v_{c_2}: \psi'(s_1,\dots,s_{c_1},\alpha_w(u_1),\dots,\alpha_w(u_{i+1}),v_{i+2},\dots,v_{c_2}).
        \end{align*}
         This coincides with the statement $f_d(w) \models \psi_{i+1}(s_1,\dots,s_{c_1},\alpha_w(u_1),\dots,\alpha_w(u_{i+1}))$, and thus completes the proof of Case 1. 

        \textbf{Case 2, $i + 1 \not \in X$:} In this case, the inductive assumption implies that
        \begin{align*}
            f_d(w) \models \exists v_{i+1} Q_{i+2} v_{i+2} \dots Q_{c_2} v_{c_2}: \psi'(s_1,\dots,s_{c_1},\alpha_w(u_1),\dots,\alpha_w(u_i),v_{i+1},\dots,v_{c_2}). 
        \end{align*}
        Let $\gamma$ denote a constant chosen so that 
        \begin{align*}
            f_d(w) \models Q_{i+2} v_{i+2} \dots Q_{c_2} v_{c_2}: \psi'(s_1,\dots,s_{c_1},\alpha_w(u_1),\dots,\alpha_w(u_i),\gamma, v_{i+2},\dots,v_{c_2}). 
        \end{align*}
        Note that $\gamma$ only depends on the tuple $\underline{s}$, and the choices of $\alpha_w(u_1),\dots,\alpha_w(u_i)$. Let $u_{i+1} = \alpha_w^{-1}(\gamma)$, and note that $\alpha_w^{-1}(\gamma)$ is well-defined since $\alpha_w$ is a bijection. Since $\alpha_w$ is a bijection, the inductive assumption implies that the tuple $(\alpha_w(u_1),\dots,\alpha_w(u_{i}))$ only depends on the tuple $\underline{t}$ and the values of $(\underline{\hat{u}}_j: j \in X, j \leq i)$. Thus $u_{i+1}$ chosen in this way satisfies both the second and the third condition, as required. 
    \end{proof}

    Fix a sequence $s_1,\dots,s_{c_1}$ and a $X$-tuple $\hat{\underline{u}} = (\hat{u}_i: i \in X)$ for which we have $f_d(w) \models \psi(s_1,\dots,s_{c_1})$, and let $\underline{t}$ and $\underline{u}$ be constructed as in the statement of Claim~\ref{claim: extending sequences}. Applying Claim~\ref{claim: extending sequences} with $j = c_2$ yields that 
    \[f_d(w) \models \psi'(s_1,\dots,s_{c_1},\alpha_w(u_1),\dots,\alpha_w(u_{c_2})).\]
    Recall that $s_i = \alpha_w(t_i)$ for each $i$. Given $i$ and $j$, let $x_\psi$  and $y_\psi$ denote the variables occurring in the formula $p_{i,j} := p_{i,j}(x_\psi,y_\psi)$. By construction, we have $q_{i,j} := q_{i,j}(x_\phi,y_\phi)$, and depending on the type of the atomic formula used to construct $p_{i,j}$, Lemma~\ref{lemma: easy cases = and in} or Lemma~\ref{lemma: inductive step of leq_1 correspondence} respectively implies that for all $a$ and $b$ we have $w \models q_{i,j}(a,b)$ if and only if $f_d(w) \models p_{i,j}(\alpha_w(a),\alpha_w(b))$. Since $\alpha_w$ is a bijection, it follows that 
    \[w \models \phi'(t_1,\dots,t_{c_1},u_1,\dots,u_{c_2}).\]

    Since the conclusion holds for an arbitrary $X$-tuple $\hat{\underline{u}}$, and the values of $u_j$ with $j \not \in X$ only depend on the values of $\hat{\underline{u}}_i$ with $i < j$, we may use these values to assign correct choices for the variables attached with $\exists$-quantifiers. Hence, we conclude that 
    \[w \models \phi(t_1,\dots,t_{c_1}).\]
    Since $t_i = \alpha_w^{-1}(s_i)$ and $\alpha_w$ is a bijection, this completes the proof. Proof of the other direction, i.e.\ of the fact that $w \models \phi(a_1,\dots,a_{c_1})$ implies $f_d(w) \models \psi(\alpha_w(a_1),\dots,\alpha_w(a_{c_1}))$ follows analogously - we omit the details.  

    If $\psi$ is a first-order formula, then all bound and free variables in $\psi$ are first-order variables, and none of the $p_{i,j}$'s is of the form $x_\psi \in y_\psi$ or its negation for some variables $x_\psi$ and $y_\psi$. Thus the same must be true for the variables and formulae $q_{i,j}$ in $\phi$, whence $\phi$ must be a first-order formula  as well. This completes the proof of Theorem~\ref{thm: FO correspondence}.

\label{claim: extending sequences}
        Let $\underline{s}$ be a $[c_1]$-tuple of constants in $f_d(w)$ with correct orders with respect to the variables $v^{(f)}_i$ chosen so that $f_d(w) \models \psi(s_1,\dots,s_{c_1})$. Let $\underline{t}$ denote the $[c_1]$-tuple of constants in $w$ chosen so that $t_i = \alpha_w^{-1}(s_i)$ for each $i \in [c_1]$, and let $\hat{\underline{u}} = (\hat{u}_i: i \in X)$ denote an arbitrary $X$-tuple of constants in $w$ of the correct orders. There exists a $[c_2]$-tuple of constants $\underline{u}$ for which the following properties hold for every $j \in \{0,1,\dots,c_2\}$:
