        Let $\gamma$ denote a constant chosen so that 
        \begin{align*}
            f_d(w) \models Q_{i+2} v_{i+2} \dots Q_{c_2} v_{c_2}: \psi'(s_1,\dots,s_{c_1},\alpha_w(u_1),\dots,\alpha_w(u_i),\gamma, v_{i+2},\dots,v_{c_2}). 
        \end{align*}
        Note that $\gamma$ only depends on the tuple $\underline{s}$, and the choices of $\alpha_w(u_1),\dots,\alpha_w(u_i)$. Let $u_{i+1} = \alpha_w^{-1}(\gamma)$, and note that $\alpha_w^{-1}(\gamma)$ is well-defined since $\alpha_w$ is a bijection. Since $\alpha_w$ is a bijection, the inductive assumption implies that the tuple $(\alpha_w(u_1),\dots,\alpha_w(u_{i}))$ only depends on the tuple $\underline{t}$ and the values of $(\underline{\hat{u}}_j: j \in X, j \leq i)$. Thus $u_{i+1}$ chosen in this way satisfies both the second and the third condition, as required.

\label{prop: small classes FOS classifiable}
    Let $\mathcal{F}$ be a finitely based permutation class. There exists a first-order formula $\upsilon_{\mathcal{F}}(x_1,x_2,y_1,y_2)$ for which $\sigma \models \upsilon_{\mathcal{F}}(a_1,a_2,b_1,b_2)$ if and only if the sub-permutation $\tau$ of $\sigma$ is contained in $\mathcal{F}$, where $\tau$ is induced by the points $p$ in $\sigma$ which satisfy the condition $p \in [a_1,b_1]_1 \times [a_2,b_2]_2$. 

    In particular, there exists a first-order sentence $\hat{\upsilon}_{\mathcal{F}}$ for which we have  $\sigma \models \hat{\upsilon}_{\mathcal{F}}$ if and only if $\sigma \in \mathcal{F}$.

\label{lemma: handling Q_ks for bijection}
    \begin{enumerate}
        \item Let $\tau$ be a permutation in $\widetilde{\mathcal{O}}_k$. There exists a first-order formula $\psi_{\tau,<_L}(x_{i,u,v})$ with variables $x_{i,u,v}$ for $i \in \{1,\dots,|\tau|\}$ and $u,v \in \{1,2\}$ so that $\sigma \models \psi_{\tau,<_L}(a_{i,u,v})$ if and only if the left-greedy decomposition of $\sigma$ is given by $\tau[\sigma_1,\dots,\sigma_{|\tau|}]$, where the points $a_{i,u,1}$ and $a_{i,u,2}$ are respectively the least and greatest points of $\sigma_i$ in the order $\leq_u$ for $u \in \{1,2\}$, and each $\sigma_i$ consists of the points in $[a_{i,1,1},a_{i,1,2}]_1 \times [a_{i,2,1},a_{i,2,2}]_2$. 
        \item Let $\hat{\Delta}$ be a first-order sentence in $\Sigma_{d-1}^* $. Given $\tau \in \mathcal{Q}_k$,  there exists a first-order formula $\Delta_\tau(\nu_{i,u,v})$ with $i \in \{1,\dots,|\tau|\}$, and $u,v\in\{1,2\}$ for which $w \models \Delta_\tau(c_{i,u,v})$ if and only if the following conditions hold:
        \begin{enumerate}
            \item $f_d(w) \neq \star$ and $w$ has profile $\tau$;
            \item if $w$ decomposes as $w = u_1\dots u_{|\tau|}$, then we have $\rho_1(u_i) \models \hat{\Delta}$ for each $i$; and
            \item the left-greedy decomposition of $f_d(w)$ is given by $\tau[f_{d-1}(\rho_1(u_1)),\dots,f_{d-1}(\rho_1(u_{|\tau|}))]$, and we have $f_d(w) \models \psi_{\tau,<_L}(\alpha_w(c_{i,u,v}))$. 
        \end{enumerate}
    \end{enumerate}

    In~\cite{ourotherpaper}, we also require an analogous version of Lemma~\ref{lemma: handling Q_ks for bijection} to determine the end-points of the first $B$ blocks when the profile $\tau$ is a monotone permutation of arbitrary length. As the construction is somewhat similar to the proof of Lemma~\ref{lemma: handling Q_ks for bijection}, we state and prove this result in the Appendix. 
    \begin{proof}
    \textbf{Proof of statement 1:} Given a positive integer $t$, define the auxiliary first-order formula $\psi_{\geq,t}(x_1,\dots,x_t,y_1,\dots,y_t)$ as
        \begin{align*}
            \bigwedge_{j = 1}^{t} \left(\left(\bigwedge_{i=1}^{j-1} x_i = y_i\right) \implies  y_j \leq_1 x_j\right).
        \end{align*}
        Note that the first term corresponding to $j = 1$ is simply $y_1 \leq_1 x_1$. Let $S_{\tau} = \{\tau' \in \widetilde{\mathcal{O}}_k: |\tau'| < |\tau|\}$. Define $\psi_{\tau,<_L}(x_{i,u,v})$ to be the formula 
        \begin{align*}
            & \psi_{\tau}(x_{i,u,v}) \\
            & \land \bigwedge_{\tau' \in S_{\tau}} \left(\forall_{i \in [|\tau'|], u,v\in \{1,2\}} y_{i,u,v}: (\neg \psi_{\tau'}(y_{i,u,v}))\right) \\
            & \land \left(\forall_{i \in [|\tau|], u,v\in \{1,2\}} y_{i,u,v}: \psi_{\tau}(y_{i,u,v}) \implies \psi_{\geq, |\tau|}(x_{i,1,2},y_{i,1,2})\right).
        \end{align*}
        Suppose that $\sigma \models \psi_{\tau,<_L}(a_{i,u,v})$. For each $i$, let  $\sigma_i$ denote the sub-permutation of $\sigma$ consisting of points $p$ in $[a_{i,1,1},a_{i,1,2}]_1 \times [a_{i,2,1},a_{i,2,2}]_2$. The first line of $\psi_{\tau,<_L}$ implies that $\sigma = \tau[\sigma_1,\dots,\sigma_{|\tau|}]$, and our goal is to show that $\tau[\sigma_1,\dots,\sigma_{|\tau|}]$ is the left-greedy decomposition of $\sigma$. 

        Suppose that $\tau' \in \widetilde{\mathcal{O}}_k$ and $\sigma_1',\dots,\sigma'_{|\tau'|} \in \widetilde{\mathcal{O}}_k^{[d-1]}$ are chosen so that $\sigma = \tau'[\sigma_1',\dots,\sigma'_{|\tau'|}]$, and suppose for the sake of contradiction we have  $\tau'[\sigma'_1,\dots,\sigma'_{|\tau'|}]<_{L}\tau[\sigma_1,\dots,\sigma_{|\tau|}]$. First consider the case when $|\tau'|< |\tau|$. Let $b_{i,u,v}$ be chosen so that $\sigma'_i$ consists of the points in $[b_{i,1,1},b_{i,1,2}]_1\times[b_{i,2,1},b_{i,2,2}]_2$. Note that such $b_{i,u,v}$ exist, as each $\sigma_i'$ is a sub-interval of $\sigma$. Choosing $y_{i,u,v} = b_{i,u,v}$ for this particular choice of $\tau'$ for each $i \in [|\tau'|]$  on the second line of $\psi_{\tau,<_L}$ gives the desired contradiction. 

        Now suppose that $|\tau'| = |\tau|$. Proposition~2.3 in~\cite{albert2015inflations} implies that for any $\sigma \in \widetilde{\mathcal{O}}_{k}^{[d]}$, the set $T(\sigma)$ of possible profiles $\tau'$  of decompositions of $\sigma$ as $\sigma = \tau'[\sigma_1,\dots,\sigma_\ell]$ with $\sigma_i \in \widetilde{\mathcal{O}}_{k}^{[d-1]}$ has a unique minimum element under sub-pattern containment. In particular, since $\tau$ is an element of minimal size in $T(\sigma)$, we must have $\tau \leq \tau'$ and thus $\tau = \tau'$. 

        Let $t$ be chosen so that $|\sigma_i| = |\sigma_i'|$ for every $i \leq t-1$ and $|\sigma_t'| > |\sigma_t|$. Let $b_{i,u,v}$ be chosen as above, and choose $y_{i,u,v} = b_{i,u,v}$ on the last line of $\psi_{\tau, <_L}$. Since $\sigma \models \psi_{\tau}(b_{i,u,v})$, we must have $\psi_{\geq,|\tau|}(a_{i,1,2},b_{i,1,2})$. In particular, we have 
        \begin{align} \label{eq: leftgreedy contradiction}
            \sigma \models \left(\left(\bigwedge_{i=1}^{t-1} a_{i,1,2} = b_{i,1,2}\right) \implies b_{t,1,2} \leq_1 a_{t,1,2}\right). 
        \end{align}
        Note that for each $i$, $a_{i,1,2}$ is the largest point in $\sigma_i$ with respect to $\leq_1$, and analogously $b_{i,1,2}$ is the largest point in $\sigma_i'$. Thus, the condition $a_{i,1,2} = b_{i,1,2}$ is equivalent to 
        \begin{align*}
            \sum_{j=1}^{i} |\sigma_j| = \sum_{j=1}^i |\sigma_j'|
        \end{align*}
        and the condition $b_{i,1,2} \leq_1 a_{i,1,2}$ is equivalent to\begin{align*}
            \sum_{j=1}^{i} |\sigma_j| \geq \sum_{j=1}^i |\sigma_j'|. 
        \end{align*}
        In particular, the equation~\eqref{eq: leftgreedy contradiction} implies that $|\sigma_i| = |\sigma_i'|$ for every $i \leq t-1$ and $|\sigma_t'| \leq |\sigma_t|$, which gives the required contradiction. Proving the converse direction follows analogously, we omit the details. 

        \textbf{Proof of statement 2:} Given $\tau \in \mathcal{Q}_k$ we write $\ell = |\tau|$. Define the first-order formula $\chi_{\tau}(x_{i,u,v},x_i)$ involving the variables  $x_{i,u,v}$  and $x_i$ for $i\in [\ell]$, $u,v \in \{1,2\}$ by setting
        \begin{align} \label{eq: importan definition}
            \psi_{\tau,<_L}(x_{i,u,v}) \land \bigwedge_{i=1}^\ell \left(x_i \in [x_{i,1,1},x_{i,1,2}]_1\times [x_{i,2,1},x_{i,2,2}]_2\right).
        \end{align}
        Let $\hat{\Delta}_{\tau}(\nu_{i,u,v},\nu_i)$ denote the first-order formula in $\Sigma_{d}^*$ obtained by applying Theorem~\ref{thm: FO correspondence}  to $\chi_{\tau}(x_{i,u,v},x_i)$, where $\nu_i$ and $\nu_{i,u,v}$ are the variables corresponding to $x_i$ and $x_{i,u,v}$ respectively. Let $\Delta_{\tau}(\nu_{i,u,v})$ denote the first-order formula in $\Sigma_{d}^*$ given by
        \begin{align} \label{eq: Final construction}
            &\Gamma_d\land(\forall\nu:\rho_2(w_\nu)=\tau)\land\bigwedge_{i=1}^{\ell}\hat\Delta_i\\
            &\land\forall\nu_1\cdots\forall\nu_\ell:
            \left(\left(\bigwedge_{i'=1}^{\ell}\rho_3(w_{\nu_{i'}})=i'\right)
            \implies\hat\Delta_\tau(\nu_{i,u,v},\nu_i)\right),
        \end{align}
        where, as before, $\hat{\Delta}_i$ denotes the first-order sentence $\hat{\Delta}$ applied to $\rho_1(u_i)$, where $u_i$ denotes the  sub-word of $w$ which consists of those letters $w_j$ which satisfy $\rho_3(w_j) = i$. 

        To check that $\Delta_\tau$ satisfies the required properties, suppose that $w\models \Delta_\tau(c_{i,u,v})$. As the first two conditions in the expression of $\Delta_\tau$ imply that $w \models \Gamma_d$ and $\rho_2(w_i) = \tau$ for all $i$, it follows that $w$ decomposes as $w = u_1\dots u_\ell$, where $u_i$ is the sub-word of $w$ which consists of all letters $w_j$ with $\rho_3(w_j) = i$. In addition, the condition $\hat{\Delta}_i$ ensures that for each $i$ we have $\rho_1(u_i) \models \hat{\Delta}$. Thus the conditions (a) and (b) are satisfied. 

        For each $i \in \{1,\dots,\ell\}$ and $u,v\in \{1,2\}$ write $b_{i,u,v} = \alpha_w(c_{i,u,v})$, set $\sigma_i := f_{d-1}(\rho_1(u_i))$, and choose $\tau' \in \widetilde{\mathcal{O}}_k$ and $\sigma_1',\dots,\sigma_{|\tau'|}'$ so that the left-greedy decomposition of $f_d(w)$ is given by $\tau'[\sigma_1',\dots,\sigma_{|\tau'|}']$. Since each $u_i$ is non-empty, we may choose $\nu_i$ in $u_i$ for every $i$. The last condition of $\Delta_\tau$ and  Theorem~\ref{thm: FO correspondence} imply that $f_d(w) \models \psi_{\tau,<_L}(b_{i,u,v})$. Hence we must have $\tau' = \tau$, and for each $i \in \{1,\dots,\ell\}$, the permutation $\sigma_i'$ consists of points in $[b_{i,1,1},b_{i,1,2}]_1 \times [b_{i,2,1},b_{i,2,2}]_2$. On the other hand, varying a single $\nu_i$ over the indexes of $u_i$ while keeping the other choice of $\nu_j$ fixed, it is easy to see that the second condition in the construction~\eqref{eq: importan definition}, the condition $\rho_3(w_{\nu_i})= i$ in the construction~\eqref{eq: Final construction} and Theorem~\ref{thm: FO correspondence} together imply that every point corresponding to the letters of $u_i$ belongs to the rectangular block corresponding to $\sigma_i'$. Since $\alpha_w$ is a bijection, the blocks $B_i$ consisting of points corresponding to the letters of the word $u_i$ partition $f_d(w)$. Since the blocks corresponding to $\sigma_i'$ also partition $f_d(w)$, the inclusions must be equalities, and thus $B_i = \sigma_i'$ for every $i$. 

        Thus, we conclude that $\alpha_w(j) \in [b_{i,1,1},b_{i,1,2}]_1 \times [b_{i,2,1},b_{i,2,2}]_2$ if and only if $\rho_3(w_j) = i$.  Equivalently, the letter $w_j$ belongs to the sub-word $u_i$ if and only if the corresponding point $\alpha_w(j)$ belongs to $\sigma_i'$. By the recursive construction of the functions $\alpha_w$ we have $f_{d-1}(\rho_1(u_i)) = \sigma_i'$ for each $i \in \{1,\dots,\ell\}$. This verifies that the final condition (c) is also satisfied. 

        Proof of the converse direction follows analogously. 
    \end{proof}

\textbf{Proof of statement 1:} Given a positive integer $t$, define the auxiliary first-order formula $\psi_{\geq,t}(x_1,\dots,x_t,y_1,\dots,y_t)$ as
