\label{lemma: albert left greedy}
    Given $\sigma \in \widetilde{\mathcal{O}}_k^{[d]}$, the expression $\sigma_1 \oplus \dots \oplus \sigma_\ell$ with $\sigma_i \in \widetilde{\mathcal{O}}_k^{[d-1]}$ is not the left-greedy decomposition of $\sigma$ if and only if there exists $i \in \{1,\dots,\ell-1\}$ for which $\sigma_i \oplus \sigma_{i+1} = \theta_1 \oplus \theta_2$ for some $\theta_1,\theta_2 \in \widetilde{\mathcal{O}}_k^{[d-1]}$ with $|\theta_1| > |\sigma_{i}|$ (allowing the possibility that $\theta_2$ is the empty permutation). 

    An analogous statement holds when all the instances of $\oplus$ are replaced with $\ominus$.

\label{lemmma: oplus}
    There exists a first-order formula $\psi_{\oplus}(x_{i,u,v})$ with variables $x_{i,u,v}$ for $i,u,v \in \{1,2\}$ which satisfies the following conditions. For $i \in \{1,2\}$, let $\theta_i$ denote the sub-permutation consisting of the points in $[a_{i,1,1},a_{i,1,2}]_1 \times [a_{i,2,1},a_{i,2,2}]_2$. 
    \begin{enumerate}
        \item [(i)] Whenever $\sigma \models \psi_{\oplus}(a_{i,u,v})$, we have $\sigma = \theta_1 \oplus \theta_2$, and $\theta_i \in \widetilde{\mathcal{O}}_k^{[d-1]}$
        \item [(ii)] Given any decomposition of $\sigma$ as $\sigma = \theta_1 \oplus \theta_2$ for non-empty $\theta_i \in \widetilde{\mathcal{O}}_k^{[d-1]}$, let $a_{i,u,v}$ denote the extremal points in $\theta_i$ chosen as above. Then $\sigma \models \psi_{\oplus}(a_{i,u,v})$. 
    \end{enumerate}

    Similarly, there exists a first-order formula $\psi_{\ominus}(x_{i,u,v})$ satisfying the appropriate conditions with each instance of $\oplus$ replaced with $\ominus$.

We claim that we may take $\psi_{\oplus}(x_{i,u,v})$ to be the first-order formula 
    \begin{align*}
        & \left( \forall z: (z \in [x_{1,1,1},x_{1,1,2}]_1 \times [x_{1,2,1},x_{1,2,2}]_2 \lor z \in [x_{2,1,1},x_{2,1,2}]_1 \times [x_{2,2,1},x_{2,2,2}]_2) \right) \\
        \land & \left( \forall z_1 \forall z_2: \left( \bigwedge_{i=1}^2 z_i \in [x_{i,1,1},x_{i,1,2}]_1 \times [x_{i,2,1},x_{i,2,2}]_2\right) \implies \left((z_1 <_1 z_2) \land (z_1 <_2 z_2)\right)\right) \\
        \land & \bigwedge_{i=1}^2 \upsilon_{d-1,k}(x_{i,1,1},x_{i,2,1},x_{i,1,2},x_{i,2,2})\\ 
        \land &\bigwedge_{i,u,v=1}^{2}
        \left(x_{i,u,v}\in[x_{i,1,1},x_{i,1,2}]_1
        \times[x_{i,2,1},x_{i,2,2}]_2\right).
    \end{align*}
    Indeed, suppose that $\sigma \models \psi_{\oplus}(a_{i,u,v})$. Let $\theta_1$ and $\theta_2$ denote the sub-permutations defined as in the statement of the Lemma. The first line of $\psi_\oplus$ implies that every point $p \in \sigma$ belongs to at least one of $\theta_1$ or $\theta_2$, the second line implies that we have $\sigma = \theta_1\oplus \theta_2$, and the third line implies that we have $\theta_1,\theta_2 \in \widetilde{\mathcal{O}}_k^{[d-1]}$. Finally, the last line ensures that each of these rectangles is non-empty, and its specified endpoints are indeed its extremal points. Proving the converse follows similarly, we omit the details.

\label{lemma: sum decomposition lemma}
    There exists a first-order formula $\psi_{\mathrm{inc}}(k_{1},\ell_1,k_2,\ell_2) \in \mathrm{FO}(\Sigma_{d}^*)$ so that $w \models \psi_{\mathrm{inc}}(a_{1},b_1,a_2,b_2)$ if and only if the following conditions hold:
    \begin{enumerate}
        \item $w \models \Gamma_d$, $\rho_2(w_1) = \mathrm{inc}$, and there exists $j$ so that $u_j$ and $u_{j+1}$ coincide with the sub-words $w_{a_1}\dots w_{b_1}$ and $w_{a_2} \dots w_{b_2}$ respectively; and 
        \item if $f_{d-1}(\rho_1(u_j)) \oplus f_{d-1}(\rho_1(u_{j+1})) = \theta_1 \oplus \theta_2$ for such choice of $j$ as above, and for some (possibly empty) permutations $\theta_1, \theta_2 \in \widetilde{\mathcal{O}}_k^{[d-1]}$, we have $|\theta_1| \leq |f_{d-1}(\rho_1(u_j))|$. 
    \end{enumerate}
    Similarly, there exists a first-order formula $\psi_{\mathrm{dec}}(k_1,\ell_1,k_2,\ell_2)$ which satisfies analogous conditions with $\oplus$ replaced by $\ominus$.

\label{claim: central for bijection}
        We have $w\models\Delta_d$ if and only if 
        \begin{enumerate}
            \item for every $i$ we have $\rho_1(u_i)\models\Delta_{d-1}$,
            \item the expression $\tau'[\sigma_1,\dots,\sigma_\ell]$ is the left-greedy decomposition of the respective permutation, and
        \item $\tau\neq \mathrm{dec}$ when $\ell=1$.
        \end{enumerate}

Let $\Gamma_M$ be the first-order sentence 
\begin{align*}
&\forall i\forall j\,\Bigl[
 \bigwedge_{(a_1,b_1)\in\mathcal S_\pm}
 \bigwedge_{(a_2,b_2)\in\mathcal S_\star}
 ((\rho_6(w_i)=(a_1,b_1)\land\rho_6(w_j)=(a_2,b_2))\implies i<j)
 \Bigr]\\
&\land\forall i\forall j\,\Bigl[
 \bigwedge_{(a_1,b_1),(a_2,b_2)\in\mathcal S_\star}
 ((\rho_6(w_i)=(a_1,b_1)\land\rho_6(w_j)=(a_2,b_2)\land i<j)
   \implies a_1\leq a_2)\Bigr]\\
&\land\bigwedge_{(a,b)\in\mathcal S_\star}
 \Bigl((\exists u\colon\rho_6(w_u)=(a,b))
       \implies(\Gamma_d)_{(a,b)}\Bigr).
\end{align*}
As before, $(\Gamma_d)_{(a,b)}$ denotes the first-order sentence $\Gamma_d$ applied to the word $\rho_5(u_{(a,b)})$. In order to check that $\Gamma_M$ satisfies the required properties, suppose that $w \models \Gamma_M$. The first line of $\Gamma_M$ implies that $w$ is of the form $w = u_0w'$ for some $w' \in \left(\Sigma_M \setminus \Sigma_{M,\pm}\right)^*$, and the second line implies that each letter in $u_{(i,j)}$ must precede the letters of $u_{(i',j')}$ for every $(i,j),(i',j') \in \mathcal{S}_\star$ with $i < i'$. In particular, we must have $w = u_0u_{(i_1,j_1)}\dots u_{(i_r,j_r)}$. Finally, the last line implies that for every $1 \leq s \leq r$, either $u_{(i_s,j_s)}$ is empty or $\rho_5(u_{(i_s,j_s)}) \models \Gamma_{d}$. The proof that for every $w \in \Sigma_M^*$ with $f_M(w) \neq \star$ we have $w  \models \Gamma_M$ follows analogously.

\label{lemma: easy cases = and in M}
    Let $w \in \Sigma_M^*$ be chosen so that $w \models \Gamma_M$. 
    \begin{enumerate}
        \item Let $\psi(x,y)$ denote the $\mathrm{MSO}$-$\mathrm{TOTO}$ formula given by $x = y$, and $\phi(x',y')$ denote the formula in $\mathrm{MSO}(\Sigma_M^*)$  given by $x' = y'$. We have $w \models \phi(a,b)$ if and only if $f_M(w) \models \psi(\alpha_{w,M}(a), \alpha_{w,M}(b))$. 
        \item Let $\psi(x,z)$ denote the $\mathrm{MSO}$-$\mathrm{TOTO}$ -formula given by $x \in z$, and $\phi(x',z')$ denote the formula in $\mathrm{MSO}(\Sigma_M^*)$ given by $x' \in z'$. We have $w \models \phi(a,c)$ if and only if $f_M(w) \models \psi(\alpha_{w,M}(a), \alpha_{w,M}(c))$. Here, we define $\alpha_{w,M}(c) := \{\alpha_{w,M}(t): t\in c\}$. 
    \end{enumerate}

\label{thm: FO correspondence for M}
    Let $v^{(f)}_1,\dots,v^{(f)}_{c_1},v^{(b)}_1,\dots,v^{(b)}_{c_2}$ denote variables (either first or second-order variables), with $v^{(f)}_i$'s corresponding to free and $v^{(b)}_i$'s corresponding to bound variables. Let $\psi(v^{(f)}_1,\dots,v^{(f)}_{c_1})$ denote a monadic second-order formula in $\mathrm{TOTO}$ given in disjunctive normal form, i.e.\
    \begin{align*} 
        \psi(v^{(f)}_1,\dots,v^{(f)}_{c_1}) = Q_1 v^{(b)}_1\dots Q_{c_2} v^{(b)}_{c_2} \left(\left(p_{1,1} \land \dots \land p_{1,a_1}\right) \lor \dots \lor \left(p_{b,1} \land \dots  \land p_{b,a_b}\right)\right),
    \end{align*}
    where each $p_{i,j}$ is an atomic formula or its negation using variables in $v^{(f)}_1,\dots,v^{(f)}_{c_1},v^{(b)}_1,\dots,v^{(b)}_{c_2}$. There exists a monadic second-order formula $\phi$ in $\Sigma_M^*$ of the form 
    \begin{align*}  
        \phi(\nu^{(f)}_1,\dots,\nu^{(f)}_{c_1}) = Q_1 \nu^{(b)}_1 \dots Q_{c_2} \nu^{(b)}_{c_2}: \left(q_{1,1} \land \dots \land q_{1,a_1}\right) \lor \dots \lor \left(q_{b,1} \land \dots \land q_{b,a_b}\right)
    \end{align*}
    satisfying the following properties:
    \begin{enumerate}
        \item each variable $\nu^{(f)}_i$ and $\nu^{(b)}_j$ has the same order as the respective variable $v^{(f)}_i$ and $v^{(b)}_j$;
        \item each formula $q_{i,j}$ depends only on the formula $p_{i,j}$; and 
        \item for each $a_1,\dots,a_{c_1}$ and $w \in \Sigma_M^*$ satisfying $w \models \Gamma_M$, we have $w \models \phi(a_1,\dots,a_{c_1})$ if and only if $f_M(w) \models \psi(\alpha_{w,M}(a_1),\dots,\alpha_{w,M}(a_{c_1}))$. 
    \end{enumerate}

    In addition, if $\psi$ is a first-order formula, then so is $\phi$.

\label{lemma: cells indexed by A}
    Let $A \subseteq \mathcal{S}$ be a collection of non-zero entries of $M$. There exists a first-order formula $\psi_A(x_{(i,j),u,v})$ involving variables $x_{(i,j),u,v}$ for $(i,j) \in A$, $u,v\in \{1,2\}$ so that $\sigma \models \psi_A(c_{(i,j),u,v})$ for some constants $c_{(i,j),u,v}$ if and only if there exists a gridded permutation $\sigma_\# \in G(\sigma)$  so that the following conditions are satisfied:
    \begin{enumerate}
        \item[(i)] the non-empty cells of $\sigma_\#$ are indexed exactly by $A$; and 
        \item[(ii)] for every $(i,j) \in A$, we have $p \in \sigma_\# \cap C_{i,j}$ if and only if $p \in [c_{(i,j),1,1},c_{(i,j),1,2}]_1 \times [c_{(i,j),2,1},c_{(i,j),2,2}]_2$. Moreover, each $c_{(i,j),u,v}$ belongs to the cell $\sigma_\# \cap C_{i,j}$. 
    \end{enumerate}

\label{lemma: left-greedy comparison lemma}  
    Let $A, B \subseteq \mathcal{S}$. There exists a first-order formula $\lambda_{A,B}(x_{(i,j),u,v}, y_{(i',j'),u',v'})$ with variables $x_{(i,j),u,v}$ for $(i,j) \in A$, $u,v \in \{1,2\}$ and $y_{(i',j'),u',v'}$ for $(i',j')\in B$, $u',v' \in \{1,2\}$ so that  $\sigma \models \lambda_{A,B}(a_{(i,j),u,v},b_{(i',j'),u',v'})$ for some constants $a_{(i,j),u,v}$ and $b_{(i',j'),u',v'}$ if and only if both of the following conditions are satisfied:
    \begin{enumerate}
        \item[(i)] there exist gridded permutations $\sigma_{\#,a}$, $\sigma_{\#,b} \in G(\sigma)$ so that $\sigma_{\#,a}$ satisfies the conditions of Lemma~\ref{lemma: cells indexed by A} for the set $A$ and for constants $a_{(i,j),u,v}$, and  $\sigma_{\#,b}$ satisfies the conditions for the set $B$ and for constants $b_{(i,j),u,v}$; and 
        \item[(ii)] we have $\sigma_{\#,a} \leq_{LG} \sigma_{\#,b}$. 
    \end{enumerate}

Write $A_i = \{(i,j): (i,j) \in A\}$ and define $B_i$ analogously. For notational convenience, write $\underline{x}_A : = (x_{(i,j),u,v}: (i,j) \in A, u,v \in \{1,2\})$ and $\underline{y}_B = (y_{(i,j),u,v}: (i,j) \in B, u,v\in \{1,2\})$.  Given a finite set of variables $x_1,\dots,x_k$ write $y = \max_1(x_1,\dots,x_k)$ for the point $y \in \{x_1,\dots,x_k\}$ chosen so that $x_i \leq_1 y$ for all $i \in [k]$. It is easy to prove that $y$ can be expressed as a first-order formula. We also write $m_i(\underline{x}_A)$ and $m_i(\underline{y}_B)$ as shorthands for $\max_1(x_{(i,j),1,2}: j \text{ chosen so that } (i,j) \in A)$ and $\max_1(y_{(i,j),1,2}: j\text{ chosen so that } (i,j) \in B)$ respectively. Note that we define $m_i(\cdot)$ only when the maximum is taken over a non-empty set. 

     For each pair $(t,s)$, write$A_{<(t,s)} = \{(i,j)\in A: i < t, \text{ or } i=t\text{ and } j<s\}$, and define $B_{<(t,s)}$ analogously. For convenience, we slightly abuse the notation by allowing $s = \infty$, whence $A_{<(t,\infty)} = \{(i,j) \in A: i \leq t\}$. 

     Given sets $A$ and $B$ with $A_{<(t,s)} = B_{<(t,s)}$ define auxiliary formula $\omega_{<(t,s),A,B}(\underline{x}_A,\underline{y}_B)$ as 
    \begin{align*}
        \bigwedge_{(i,j) \in A_{<(t,s)}} \bigwedge_{u,v\in \{1,2\}} (x_{(i,j),u,v} = y_{(i,j),u,v}). 
    \end{align*}
    For an integer $i'$ with $A_{<(i',\infty)} = B_{<(i',\infty)}$, define $\lambda_{i',A,B}(\underline{x}_A,\underline{y}_B)$ to be the formula 
    \begin{align*}
        & \bigvee_{\substack{1\leq i\leq i'\\ A_i=B_i\ne\emptyset}} \left(\omega_{<(i-1,\infty),A,B}(\underline{x}_A, \underline{y}_B) \land \left(m_i(\underline{y}_B) <_1 m_i(\underline{x}_A)\right)\right)\\
        & \lor \bigvee_{\substack{1\leq i\leq i'\\ A_i=B_i\ne\emptyset}}\left(\omega_{<(i-1,\infty),A,B}(\underline{x}_A, \underline{y}_B) \land \left(m_i(\underline{y}_B) = m_i(\underline{x}_A)\right)\right.\\ &\qquad\left.\land \bigvee_{j: (i,j) \in A} \left(\omega_{<(i,j),A,B}(\underline{x}_A,\underline{y}_B)\land y_{(i,j),2,2}<_2 x_{(i,j),2,2}\right)\right).
    \end{align*}
    We also use the convention that $\lambda_{0,A,B}(\underline{x}_A,\underline{y}_B)$ is the false sentence. We start by proving the following preliminary claim, which describes how $\lambda_{i',A,B}$ can  be used to determine the relative order of $\sigma_{\#,a}$ and $\sigma_{\#,b}$ with respect to $<_{LG}$. 
    \begin{claim}\label{claim: lambda claim}
        Let $i'$ be chosen so that $A_{<(i',\infty)} = B_{<(i',\infty)}$. Given constants $\underline{a}_A$ and $\underline{b}_B$, suppose that we have $\sigma \models \psi_A(\underline{a}_A)$ and $\sigma \models \psi_B(\underline{b}_B)$. Then we have $\sigma \models \lambda_{i',A,B}(\underline{a}_A,\underline{b}_B)$ if and only if $\sigma_{\#,a} <_{LG} \sigma_{\#,b}$, and if at least one of the following conditions is satisfied: 
        \begin{enumerate}
            \item[(i)] the relation $\sigma_{\#,a} <_{LG} \sigma_{\#,b}$ is witnessed when condition 1 in Definition~\ref{def: left greedy}  is satisfied for some $i_* \leq i'$; or
            \item[(ii)] the relation $\sigma_{\#,a} <_{LG} \sigma_{\#,b}$ is witnessed when condition 2 in Definition~\ref{def: left greedy}  is satisfied for some $(i_*,j_*)$ with $i_* \leq i'$. 
        \end{enumerate}
    \end{claim}
    \begin{proof}
        The proof follows by observing that 
        \begin{enumerate}
            \item[(i)]$\sigma$ satisfying the condition on the first row of $\lambda_{i',A,B}$ with $i = i_*$ is equivalent to the first condition being satisfied in Definition~\ref{def: left greedy}  when $i = i_*$; and 
            \item[(ii)] $\sigma$ satisfying the condition on the second row of $\lambda_{i',A,B}$ with $i = i_*$ and $j = j_*$ is equivalent to the second condition being satisfied in Definition~\ref{def: left greedy}  with $i = i_*$ and $j = j_*$.  
        \end{enumerate}
    \end{proof}

    \noindent We now construct the formulae $C_{A,B}(\underline{x}_A, \underline{y}_B)$. When $A = B$, we set 
    \begin{align*}
        C_{A,A}(\underline{x}_A, \underline{y}_A) = \lambda_{\ell,A,A}(\underline{x}_A,\underline{y}_A) \lor \omega_{<(\ell,\infty),A,A}(\underline{x}_A,\underline{y}_A).
    \end{align*}
    By Claim~\ref{claim: lambda claim}, the first part of $C_{A,A}$ is equivalent to the condition that $\sigma_{\#,a} <_{LG} \sigma_{\#,b}$, while the second part is equivalent to the condition that $\sigma_{\#,a} = \sigma_{\#,b}$. 

    Now suppose that $A \neq B$, and let $(i',j')$ be the lex-minimal element in $A \Delta B$. In particular, we have $A_{<(i',j')} = B_{<(i',j')}$. Note that for any choice of constants $\underline{a}_A$ and $\underline{b}_B$ we must have $\sigma_{\#,a} \neq \sigma_{\#,b}$. In addition, the left-greedy order between $\sigma_{\#,a}$ and $\sigma_{\#,b}$ must be determined in column $i_*$ or cell $(i_*,j_*)$ for some $i_* \leq i'$. We split the construction into three cases based on the structure of $A$ and $B$ in the $i'$-th column of $M$.  We write $A_{i'} = \{(i',j): (i',j) \in A\}$, and define $B_{i'}$ analogously. 

    \textbf{Case 1, $A_{i'} = \emptyset$: } Since $(i',j') \in A\Delta B$, we must have $B_{i'} \neq \emptyset$. We claim that we may take $C_{A,B}(\underline{x}_A, \underline{y}_B) = \lambda_{i'-1,A,B}(\underline{x}_A, \underline{y}_B)$. Note that whenever the condition $\sigma_{\#,a} <_{LG} \sigma_{\#,b}$ is satisfied, either the first condition in Definition~\ref{def: left greedy} holds in some column $i_*$ with $i_* \leq i'-1$, or the second condition holds in some cell $(i_*,j_*)$ with $i_* \leq i'-1$. Indeed, by our previous observation,  both of these statements are true when the upper bound on $i_*$ is replaced with $i'$ instead of $i'-1$. However, the case $i_* = i'$ is impossible as $A_{i'} = \emptyset$, whence $\sigma_{\#,a}$ cannot contain any points in its $i'$-th column (while $\sigma_{\#,b}$ is guaranteed to contain at least one point in its $i'$-th column as $B_{i'} \neq \emptyset$). Thus Claim~\ref{claim: lambda claim} implies that the formula $C_{A,B}$ satisfies the required properties. 

    \textbf{Case 2, $B_{i'} = \emptyset$:} As above, we must have $A_{i'} \neq \emptyset$. We claim that 
    \begin{align*}
         C_{A,B}(\underline{x}_A,\underline{y}_B) = \lambda_{i'-1,A,B}(\underline{x}_A,\underline{y}_B) \lor \omega_{<(i'-1,\infty),A,B}(\underline{x}_A,\underline{y}_B)
    \end{align*}
    satisfies the required properties. As above, the first part of $C_{A,B}$ covers the case when $\sigma_{\#,a} <_{LG} \sigma_{\#,b}$ is witnessed when the first or second condition in Definition~\ref{def: left greedy} is satisfied either in column $i_*$ or cell $(i_*,j_*)$ respectively for some $i_* < i'$. Note that the second part is equivalent to the statement that both $\sigma_{\#,a}$ and $\sigma_{\#,b}$ contain equal number of points in each cell $(i,j)$ with $i \leq i'-1$, which immediately implies that $\sigma_{\#,a} <_{LG} \sigma_{\#,b}$, as we have $B_{i'} = \emptyset$ and $A_{i'} \neq \emptyset$. 

    \textbf{Case 3, Both $A_{i'}, B_{i'}$ are non-empty:} Since both $A_{i'}$ and $B_{i'}$ are non-empty, both $\sigma_{\#,a}$ and $\sigma_{\#,b}$ must contain a point in their $i'$-th columns. Define $C_{A,B}(\underline{x},\underline{y})$ to be the formula 
    \begin{align*}
        & \lambda_{i'-1,A,B}(\underline{x}_A,\underline{y}_B) \\
        & \lor \left(\omega_{<(i'-1,\infty),A,B}(\underline{x}_A, \underline{y}_B) \land m_{i'}(\underline{y}_B) <_1 m_{i'}(\underline{x}_A)\right) \\
        & \lor \bigvee_{j:\,(i',j)\in A,\ j<j'} \left(\omega_{<(i',j),A,B}(\underline{x}_A, \underline{y}_B) \land m_{i'}(\underline{y}_B) =m_{i'}(\underline{x}_A)\land  y_{(i',j), 2,2} <_2  x_{(i',j),2,2}\right) \\
        & \lor \left(\omega_{<(i',j'),A,B}(\underline{x}_A, \underline{y}_B) \land m_{i'}(\underline{y}_B) =m_{i'}(\underline{x}_A)\land (i',j') \in A\right),
    \end{align*}
    where the last line is only included if $(i',j') \in A$. As before, the first line of $C_{A,B}$ corresponds to the case when  $\sigma_{\#,a} <_{LG} \sigma_{\#,b}$ is witnessed either in column $i_*$ or cell $(i_*,j_*)$ with $i_* < i'$. In addition, the second line corresponds to the case when $\sigma_{\#,a} <_{LG} \sigma_{\#,b}$ is witnessed when the first condition in Definition~\ref{def: left greedy} holds in column $i'$, while the third line corresponds to the case when the second condition holds in cell $(i',j)$ with $j < j'$. Finally, the last line corresponds to the case when the second condition holds in the cell $(i',j')$, which may only happen when $(i',j') \in A$. 

    Finally, we define 
    \[\lambda_{A,B}(\underline{x}_A,\underline{y}_B) = \psi_{A}(\underline{x}_A) \land \psi_{B}(\underline{y}_B) \land C_{A,B}(\underline{x}_A,\underline{y}_B).\]
    Then $\lambda_{A,B}$ satisfies the required properties as $\psi_A$ and $\psi_B$ ensure that there exist gridded permutations associated to the tuples $x_A$ and $y_B$, and $C_{A,B}$ ensures that ¨$\sigma_{\#,a} \leq_{LG} \sigma_{\#,b}$. This completes the proof.

\label{claim: lambda claim}
        Let $i'$ be chosen so that $A_{<(i',\infty)} = B_{<(i',\infty)}$. Given constants $\underline{a}_A$ and $\underline{b}_B$, suppose that we have $\sigma \models \psi_A(\underline{a}_A)$ and $\sigma \models \psi_B(\underline{b}_B)$. Then we have $\sigma \models \lambda_{i',A,B}(\underline{a}_A,\underline{b}_B)$ if and only if $\sigma_{\#,a} <_{LG} \sigma_{\#,b}$, and if at least one of the following conditions is satisfied: 
        \begin{enumerate}
            \item[(i)] the relation $\sigma_{\#,a} <_{LG} \sigma_{\#,b}$ is witnessed when condition 1 in Definition~\ref{def: left greedy}  is satisfied for some $i_* \leq i'$; or
            \item[(ii)] the relation $\sigma_{\#,a} <_{LG} \sigma_{\#,b}$ is witnessed when condition 2 in Definition~\ref{def: left greedy}  is satisfied for some $(i_*,j_*)$ with $i_* \leq i'$. 
        \end{enumerate}

The proof follows by observing that 
        \begin{enumerate}
            \item[(i)]$\sigma$ satisfying the condition on the first row of $\lambda_{i',A,B}$ with $i = i_*$ is equivalent to the first condition being satisfied in Definition~\ref{def: left greedy}  when $i = i_*$; and 
            \item[(ii)] $\sigma$ satisfying the condition on the second row of $\lambda_{i',A,B}$ with $i = i_*$ and $j = j_*$ is equivalent to the second condition being satisfied in Definition~\ref{def: left greedy}  with $i = i_*$ and $j = j_*$.  
        \end{enumerate}

Recall that $\lambda_{\Box}(\nu_{i,j},\nu_{(i,j),u,v})$ is defined to be the first-order formula obtained by applying Theorem~\ref{thm: FO correspondence for M} to the formula  $x_{i,j} \in [x_{(i,j),1,1},x_{(i,j),1,2}]_1 \times [x_{(i,j),2,1},x_{(i,j),2,2}]_2.$ We also write $\hat{\Delta}_A(\nu_{(i,j),u,v})$ for the first-order formula obtained by applying Theorem~\ref{thm: FO correspondence for M} to the formula $\Delta_A(x_{(i,j),u,v})$. 

    Let $\Delta_A'$ denote the first-order sentence 
    \begin{align*}
        \Delta_A':=&\exists_{(i,j)\in A,\ u,v\in\{1,2\}} \nu_{(i,j),u,v}\,\Bigl(\hat\Delta_A(\boldsymbol\nu)\\
        &\land\bigwedge_{(i,j)\in A}\forall t\, \bigl(\lambda_\Box(t;\nu_{(i,j),u,v}) \iff\rho_6(w_t)=(i,j)\bigr)\Bigr),
    \end{align*}
    and set 
    \begin{align*}
        \hat\Delta_M:=&\Gamma_M\land \bigvee_{A\subseteq\mathcal S}\Delta_A'.
    \end{align*}
    We claim that  $\hat\Delta_M$ satisfies the required properties. 

    Suppose that $w \models \Delta_A' \land \Gamma_M$ for some  $A \subseteq S$. Since $w \models \Gamma_M$, $w$ decomposes as $w = u_0u_{(i_1,j_1)} \dots u_{(i_r,j_r)}$. In addition, the second line of $\Delta_A'$ implies that for every $i$, the letter $w_i$ belongs to the sub-word $u_{(i_s,j_s)}$ if and only if $\beta_{w,M}(i) \in g_M(w) \cap C_{i_s,j_s}$. Thus for every $(i,j) \in A \cap \mathcal{S}_\pm$  we have $\beta_{w,M}(\ell) \in g_M(w) \cap C_{i,j}$ if and only if $\rho_6(w_\ell) = (i,j)$. In particular, the letter $w_\ell$ must belong to the sub-word $u_0$. 

    Thus, for every such $w$ we have $g_{M}(w) \cap C_{(i_s,j_s)} = f_d(\rho_5(u_{(i_s,j_s)}))$ and $g_M(w) \setminus \left(\bigcup_{s=1}^r C_{(i_s,j_s)}\right) = g_{M_{\pm 1}}(u_0)$. Hence the result follows from the first-order correspondence provided by Theorem~\ref{thm: FO correspondence for M}.

\label{thm: Perron frobenius irreducible}
    Let $A$ be an irreducible matrix with non-negative entries, and let $\lambda = \rho(A)$ denote its spectral radius. Then the following conditions are satisfied.
    \begin{enumerate}
        \item Both the left and right eigenspace associated with $\lambda$ have dimension $1$. 
        \item There exists both left and right eigenvectors $v$ and $w$ respectively associated with $\lambda$ which have positive entries. 
    \end{enumerate}
    Furthermore, if $A$ is primitive, then any eigenvalue $\mu \neq \lambda$ satisfies $|\mu| < |\lambda|$.

\label{lemma: first spectral drops lemma}
    Let $n$ and $m$ be positive integers, and let $A$ and $B$ be $(n+m)\times(n+m)$ matrices with non-negative entries satisfying the following properties.
    \begin{enumerate}
        \item $A$ is irreducible,
        \item $A_{i,j} \geq B_{i,j}$ for all $i,j$, and $A_{i,j} = B_{i,j}$ for every $1\leq i,j \leq n$, and 
        \item The $n \times n$ sub-matrix of $B$ corresponding to the top-left corner is irreducible, and $B_{i,j} = 0$ whenever $\max(i,j) \geq n+1$. 
    \end{enumerate}
    Let $\lambda = \rho(A)$ and $\mu = \rho(B)$. Then $\mu < \lambda$.

\label{lemma: loose radius or maintain aperiodicity}
    Let $\mathcal{A}$ and $\mathcal{B}$ be finite deterministic automata over the same alphabet so that $\mathcal{B}$ is complete and satisfies~\eqref{eq: iterate}. Let $D$ be a strongly connected component in the automaton $\mathcal{A} \times \mathcal{B}$ containing at least one edge, and let $C$  be the strongly connected component of $\mathcal{A}$ containing the projection of $D$. 

    Write $\lambda_C = \rho(A_C)$ and $\lambda_D= \rho(A_D)$. Then $\lambda_D \leq \lambda_C$. If equality holds, $C$ contains a cycle and is aperiodic, then $D$ must also be aperiodic.

By Perron-Frobenius (Theorem~\ref{thm: Perron frobenius irreducible}), $\lambda$ is an eigenvalue of $A$, and $A$ has a corresponding left eigenvector $v$ with positive entries. Let $B'$ denote the top-left corner of $B$. Since the last $m$ rows and columns of $B$ are identically $0$, it is easy to see that $\rho(B) = \rho(B')$, and all the eigenvectors of $B$ associated with non-zero eigenvalues are of the form $(w_1,\dots,w_n,0,\dots,0)$, where $(w_1,\dots,w_n)$ is an eigenvector of $B'$ associated with the same eigenvalue. Thus, by Perron-Frobenius there exists a right eigenvector $w$ of $B$ corresponding to $\mu$ which satisfies $w_i > 0$ for every $1 \leq i \leq n$, and $w_i = 0$ for $n+1 \leq i\leq n+m$. 

    Since $A_{i,j} \geq B_{i,j}$ for every $(i,j)$, we conclude that 
    \begin{align}\label{eq: pointwise comp}
        (Aw)_i = \sum_{j=1}^{n+m}A_{i,j}w_j \geq \sum_{j=1}^{n+m} B_{i,j}w_j = (Bw)_i = \mu \cdot w_i.
    \end{align}
    Hence, we conclude that 
    \begin{align} \label{eq: critical inequality}
        \lambda \cdot v^Tw = v^TAw =\sum_{i=1}^{n+m} v_i\cdot (Aw)_i \geq \sum_{i=1}^{n+m} \mu \cdot v_i\cdot w_i = \mu\cdot v^Tw,
    \end{align}
    where the inequality in the middle follows from~\eqref{eq: pointwise comp}. Thus, we conclude that $\lambda \geq \mu$. 

    If $\lambda = \mu$, then inequality~\eqref{eq: critical inequality} must be tight. Since $v_i > 0$ for every $i$, we conclude that the inequality~\eqref{eq: pointwise comp} in turn must be tight for every $i$. Since $w_j > 0$ for every $1 \leq j \leq n$, this in turn implies that we must have $A_{i,j} = B_{i,j}$ for every $1 \leq j \leq n$ and every $1 \leq i \leq n+m$. In particular, this means that $A_{i,j} = 0$ for every  $i \in \{n+1,\dots,n+m\}$ and $j\in \{1,\dots,n\}$, which contradicts the fact that $A$ is irreducible. Thus we must have $\mu < \lambda$.

\label{lemma: important properties of h}
    \begin{enumerate}
        \item $|h(w)| = |w|$ for every $w \in L_\mathcal{C}$.
        \item $h$ is an injection.
        \item The image of $h$ is contained in $\mathcal F$.

    \end{enumerate}

Recall that every $w \in L_{\mathcal{C}}$ decomposes as $w = u_1 \dots u_m$ so that 
    \begin{align}\label{eq: left greedy for h}
        h(w) = \sigma_1\oplus \dots \oplus \sigma_m,
    \end{align} 
    where $\sigma_i = f_{j-1}(\rho_1(\pi(u_i)))$. In addition, recall from the proof of Lemma~\ref{lemma: important properties of h} that the right-hand side of the equation~\eqref{eq: left greedy for h} also coincides with the left-greedy decomposition of $h(w)$ when viewed as an element of $\widetilde{\mathcal{O}}_{k}^{[j]}$. Thus $\pi(w) \models \Delta_{j}$, and hence the result follows from Lemma~\ref{lemma: no long monotone subintervals for fs}.

